    ["<HyperLink stylename=\"M_Link\" u=\"86011040\" color=\"#f4a067\">逐日</>造成伤害提高15%。"] = "Урон <HyperLink stylename=\"M_Link\" u=\"86011040\" color=\"#f4a067\">Sun Chaser</> увеличен на 15%.",
